package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.accessibilityservice.AccessibilityServiceInfo;import android.graphics.Rect;import android.view.*;import android.view.accessibility.AccessibilityWindowInfo;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;import org.json.*;
/** Synthetic projects only; raw widgets and actions are tested around genuine Activity destruction. */
final class ManagerFormChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;
 ManagerFormChecks(MapAndroidChecks checks){m=checks;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);}
 TextView errorView(View view){if(view instanceof TextView&&!(view instanceof EditText)&&((TextView)view).getCurrentTextColor()==0xffb00020)return (TextView)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){TextView result=errorView(g.getChildAt(i));if(result!=null)return result;}}return null;}
 String state(){final String[] result={null};m.runOnMainSync(()->{try{View root=m.activeDialogRoot();List<EditText> fields=new ArrayList<>();m.collectInputs(root,fields);List<Spinner> spinners=new ArrayList<>();List<CheckBox> boxes=new ArrayList<>();m.listingWidgets(root,spinners,boxes);JSONObject o=new JSONObject();JSONArray inputs=new JSONArray(),choices=new JSONArray(),checks=new JSONArray();for(EditText input:fields)inputs.put(new JSONArray().put(input.getText().toString()).put(input.getSelectionStart()).put(input.getSelectionEnd()).put(input.hasFocus()));for(Spinner spinner:spinners)choices.put(spinner.getSelectedItemPosition());for(CheckBox box:boxes)checks.put(box.isChecked());TextView error=errorView(root);o.put("inputs",inputs);o.put("spinners",choices);o.put("checks",checks);o.put("error",error==null?"":error.getText().toString());result[0]=o.toString();}catch(Exception e){throw new RuntimeException(e);}});return result[0];}
 Map<String,?> prefs(){return new HashMap<>(m.getTargetContext().getSharedPreferences("object-manager-view",0).getAll());}
 void keyboard(int index,boolean seed)throws Exception{m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);EditText input=fields.get(index);if(seed){input.requestFocus();input.setSelection(3,Math.min(8,input.length()));}((InputMethodManager)m.activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);});long end=System.currentTimeMillis()+7000;while(v.imeWindows().length()==0&&System.currentTimeMillis()<end)Thread.sleep(100);m.check(v.imeWindows().length()>0,"actual IME for form field "+index);}
 void aboveIme(String label,int boundary){m.runOnMainSync(()->{View button=v.button(m.activeDialogRoot(),label);int[] xy=new int[2];if(button!=null)button.getLocationOnScreen(xy);m.check(button!=null&&v.fullyVisible(button)&&button.getHeight()>=Math.round(48*m.activity.getResources().getDisplayMetrics().density)&&xy[1]+button.getHeight()<=boundary,"full 48dp action target above actual IME: "+label);});}
 void snapshot(String name,String kind,int index,boolean ime)throws Exception{v.snapshot(name,ime,"Применить");if(!ime)return;int top=Integer.MAX_VALUE;for(AccessibilityWindowInfo window:m.getUiAutomation().getWindows())if(window.getType()==AccessibilityWindowInfo.TYPE_INPUT_METHOD){Rect rect=new Rect();window.getBoundsInScreen(rect);top=Math.min(top,rect.top);}final int boundary=top;aboveIme("Применить",top);aboveIme("Отмена",top);aboveIme(kind.equals("search")?"Сбросить":"Сбросить даты",top);m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);EditText input=fields.get(index);Rect local=new Rect(),frame=new Rect();int[] xy=new int[2];boolean visible=input.getLocalVisibleRect(local);input.getLocationOnScreen(xy);input.getWindowVisibleDisplayFrame(frame);int upper=Math.max(xy[1]+local.top,frame.top),lower=Math.min(Math.min(xy[1]+local.bottom,frame.bottom),boundary);m.check(input.hasFocus()&&input.isEnabled()&&visible&&lower-upper>=input.getLineHeight(),"focused input line above IME, field="+index);});}
 void rotate(int direction,String expected,String scene,String kind)throws Exception{Activity old=m.activity;v.rotate(direction);m.waitForIdleSync();Thread.sleep(500);m.check(old!=m.activity&&old.isDestroyed(),"actual Activity destroyed/recreated: "+scene);String actual=state();if(!expected.equals(actual))v.snapshot(scene,false);m.check(expected.equals(actual),"raw form values/cursor/focus/error restored: expected="+expected+" actual="+actual);keyboard(kind.equals("search")?0:1,false);snapshot(scene,kind,kind.equals("search")?0:1,true);}
 void seed(String kind)throws Exception{boolean dates=kind.equals("dates");m.setListingForm("QA_ROTATE_",0,0,dates?2:1,dates,dates,dates?2:0);m.setDates(1,"","");m.geometryReady();}
 void searchDraft(String outcome)throws Exception{m.click("Поиск и фильтры");m.inputs(outcome.equals("apply")?"  QA_ROTATE_  ":"  QA_RAW 😀  ");m.runOnMainSync(()->{List<Spinner> spinners=new ArrayList<>();List<CheckBox> boxes=new ArrayList<>();m.listingWidgets(m.activeDialogRoot(),spinners,boxes);m.check(spinners.size()==4&&boxes.size()==2,"all raw search controls present");int[] values={2,2,1,3};for(int i=0;i<4;i++)spinners.get(i).setSelection(values[i]);for(CheckBox box:boxes)box.setChecked(true);});m.waitForIdleSync();keyboard(0,true);}
 void datesDraft()throws Exception{m.dateForm(2,"2026-10-01","2026-10-");m.click("Применить");m.waitText("Дата: ГГГГ-ММ-ДД");keyboard(1,true);}
 void showMessage()throws Exception{m.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);long end=System.currentTimeMillis()+7000;while(v.imeWindows().length()>0&&System.currentTimeMillis()<end)Thread.sleep(100);m.check(v.imeWindows().length()==0,"Back hides only IME after actual recreation");m.runOnMainSync(()->{TextView error=errorView(m.activeDialogRoot());m.check(error!=null&&error.length()>0,"validation message retained");error.requestRectangleOnScreen(new Rect(0,0,error.getWidth(),error.getHeight()),true);});m.waitForIdleSync();Thread.sleep(250);snapshot("forms-dates-message","dates",1,false);m.runOnMainSync(()->{TextView error=errorView(m.activeDialogRoot());Rect rect=new Rect();m.check(error!=null&&error.getLocalVisibleRect(rect)&&rect.height()>0,"restored validation message visibly accessible");});}
 Object value(Object target,String field)throws Exception{return target.getClass().getField(field).get(target);}
 void matches(Object options,String query,int field,int kind,int visibility,int sort,boolean recursive,boolean first,int mode,String from,String to)throws Exception{m.check(query.equals(value(options,"query"))&&(Integer)value(options,"searchField")==field&&(Integer)value(options,"kind")==kind&&(Integer)value(options,"visibility")==visibility&&(Integer)value(options,"sort")==sort&&(Boolean)value(options,"recursive")==recursive&&(Boolean)value(options,"foldersFirst")==first,"explicitly applied search options");Object dates=value(options,"dates");m.check((Integer)value(dates,"mode")==mode&&from.equals(value(dates,"from"))&&to.equals(value(dates,"to")),"explicitly applied date options");}
 void appliedSeed(String kind)throws Exception{boolean dates=kind.equals("dates");matches(m.managerField("viewOptions"),"QA_ROTATE_",dates?2:0,0,0,dates?2:1,dates,dates,1,"","");}
 long insert(Object store,String title)throws Exception{Object doc=r.parse(ManagerRotationChecks.XML.getBytes("UTF-8"));m.staticCall("MediaLinks","add",new Class[]{m.codec,org.w3c.dom.Element.class,String.class,String.class,byte[].class},doc,m.element(doc,"point"),"form.jpg","image/jpeg",new byte[]{1,3,5,7});return (Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,title);}
 void launch(long id)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);}
 void scenario(Object store,String kind,String outcome)throws Exception{long id=insert(store,"QA_FORMS_"+kind+"_"+outcome);try{Object doc=r.load(store,id);byte[] before=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));launch(id);seed(kind);Map<String,?> original=prefs();Set<String> originalVisible=new HashSet<>(m.managerKeys("visible"));if(kind.equals("search"))searchDraft(outcome);else datesDraft();String raw=state();appliedSeed(kind);m.check(original.equals(prefs()),"typing/invalid Apply never applies draft");if(outcome.equals("cancel"))snapshot("forms-"+kind+"-before",kind,kind.equals("search")?0:1,true);
  rotate(UiAutomation.ROTATION_FREEZE_90,raw,"forms-"+kind+"-"+outcome,kind);appliedSeed(kind);m.check(original.equals(prefs())&&originalVisible.equals(new HashSet<>(m.managerKeys("visible"))),"recreation leaves applied filters/list unchanged");m.check(m.activity.getIntent().getLongExtra("project",-1)==id,"draft stays in own project");
  if(outcome.equals("cancel")){rotate(UiAutomation.ROTATION_FREEZE_0,raw,"forms-"+kind+"-return",kind);if(kind.equals("dates"))showMessage();v.cancel();appliedSeed(kind);m.check(original.equals(prefs()),"Cancel retains all applied settings");}
  else{if(outcome.equals("apply")){if(kind.equals("dates")){m.click("Применить");m.waitText("Дата: ГГГГ-ММ-ДД");m.check(original.equals(prefs()),"invalid Apply after recreation still does not commit");m.inputs("2026-10-01","2026-10-31");keyboard(1,true);snapshot("forms-dates-corrected","dates",1,true);}m.click("Применить");}else m.click(kind.equals("search")?"Сбросить":"Сбросить даты");m.geometryReady();m.waitText("Объекты проекта");Object options=m.managerField("viewOptions");if(outcome.equals("reset")){if(kind.equals("search"))matches(options,"",0,0,0,0,false,false,0,"","");else matches(options,"QA_ROTATE_",2,0,0,2,true,true,0,"","");}else if(kind.equals("search"))matches(options,"QA_ROTATE_",2,2,1,3,true,true,1,"","");else matches(options,"QA_ROTATE_",2,0,0,2,true,true,2,"2026-10-01","2026-10-31");Set<String> expected=outcome.equals("reset")?new HashSet<>(kind.equals("search")?Arrays.asList("0","1","2"):Arrays.asList("0","0/0","1","2")):new HashSet<>(Arrays.asList("1"));m.check(new HashSet<>(m.managerKeys("visible")).equals(expected),"Apply/Reset produces intended visible objects");Map<String,?> applied=prefs();Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_0);m.check(old!=m.activity&&old.isDestroyed(),"post-action main really recreated");m.check(applied.equals(prefs()),"explicit applied settings survive next recreation");m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);m.check(fields.isEmpty(),"Apply/Reset does not reopen a dismissed draft");});}
  m.check(Arrays.equals(before,r.xml(r.load(store,id))),"form actions never change KML");r.sameAssets(r.load(store,id),assets);v.emit("FORM_RESULT kind="+kind+" outcome="+outcome+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,String kind)throws Exception{long source=insert(store,"QA_FORM_SOURCE"),other=-1;try{Object doc=r.load(store,source);byte[] before=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Object clone=r.parse(before);m.assets(clone).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},clone,"QA_FORM_FOREIGN");m.check(m.treeToken(doc).equals(m.treeToken(r.load(store,other))),"different project has identical XML token fixture");launch(other);m.setListingForm("QA_ROTATE_OTHER",0,0,0,false,false,0);launch(source);seed(kind);Map<String,?> original=prefs();if(kind.equals("search"))searchDraft("cancel");else datesDraft();final long target=other;m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",target)));Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"foreign project change really recreates Activity");m.check(((Long)m.managerField("project"))==other&&m.visibleText("QA_ROTATE_OTHER"),"new Activity loaded the other project");m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);m.check(fields.isEmpty(),"foreign raw form never opens even with identical XML");});snapshot("forms-foreign-"+kind,kind,0,false);matches(m.managerField("viewOptions"),"QA_ROTATE_OTHER",0,0,0,0,false,false,0,"","");m.check(original.equals(prefs()),"foreign draft does not change applied preferences");m.check(Arrays.equals(before,r.xml(r.load(store,source)))&&Arrays.equals(before,r.xml(r.load(store,other))),"foreign guard retains both KML documents");r.sameAssets(r.load(store,source),assets);r.sameAssets(r.load(store,other),assets);v.emit("FORM_FOREIGN kind="+kind+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},source);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void moveObservation(Object store)throws Exception{long id=insert(store,"QA_MOVE_OBSERVATION");try{byte[] before=r.xml(r.load(store,id));launch(id);m.click("QA_ROTATE_POINT");m.managerAction("Перенести выбранное");m.click("Корень проекта / QA_ROTATE_FOLDER");snapshot("forms-move-before","search",0,false);Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"move observation really recreates Activity");snapshot("forms-move-after","search",0,false);final boolean[] shown={false};m.runOnMainSync(()->shown[0]=v.button(m.activeDialogRoot(),"Перенести")!=null);v.emit("MOVE_OBSERVATION confirmationRestored="+shown[0]+" (collection only, not acceptance)");m.check(Arrays.equals(before,r.xml(r.load(store,id))),"observing move dialog never moves objects");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{Context c=m.getTargetContext();m.installTileFixture();int network=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(c);AccessibilityServiceInfo info=m.getUiAutomation().getServiceInfo();int flags=info.flags;info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(info);String oldKeyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(String kind:new String[]{"search","dates"})for(String outcome:new String[]{"cancel","apply","reset"})scenario(store,kind,outcome);for(String kind:new String[]{"search","dates"})foreign(store,kind);moveObservation(store);m.check(m.requests.get()==network,"raw forms issue no tile requests");}finally{v.finish();info.flags=flags;m.getUiAutomation().setServiceInfo(info);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(oldKeyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+oldKeyboard);m.call(store,"close",new Class[]{});}}
}
